export const giftCreditDefinitions={
 giftCredit:{title:'Compare an invented store-credit bonus with planned use and a cash-price alternative',fields:[
  ['giftCash','Cash paid to load the card at month zero (CAD)',100,10,5000,10],
  ['giftBonus','Bonus credit as a percentage of cash paid (%)',10,0,50,1],
  ['giftUse','Loaded credit used by the chosen horizon (%)',80,0,100,1],
  ['cashPriceGap','Same basket’s lower total cash price elsewhere (%)',5,0,30,1],
  ['giftMonths','Whole months over which the selected credit use occurs',12,1,24,1]
 ]}
};

export function giftCreditLedger(d){
 const bonus=d.giftCash*d.giftBonus/100,loaded=d.giftCash+bonus,used=loaded*d.giftUse/100,remaining=Math.max(0,loaded-used),priceFactor=1-d.cashPriceGap/100;
 const alternativeCash=used*priceFactor,cashDifference=d.giftCash-alternativeCash;
 const rows=Array.from({length:d.giftMonths+1},(_,month)=>{
  const redeemed=month===d.giftMonths?used:used*month/d.giftMonths;
  return {month,redeemed,remaining:Math.max(0,loaded-redeemed),cardCash:d.giftCash,alternativeCash:redeemed*priceFactor};
 });
 return {bonus,loaded,used,remaining,alternativeCash,cashDifference,bonusOnPaid:bonus/d.giftCash,discountAtFullSamePrice:bonus/loaded,cashCatchUpUse:d.giftCash/(loaded*priceFactor),fullUseCashSaving:loaded*priceFactor-d.giftCash,rows};
}

export function giftCreditResult(kind,d){
 if(kind!=='giftCredit')throw Error('Unknown gift-credit comparison.');
 const p=giftCreditLedger(d),uses=[...new Set([0,25,50,75,100,d.giftUse])].sort((a,b)=>a-b);
 return {metrics:[['Purchases deducted from card by the horizon',p.used,'money'],['Restricted credit still held at the horizon',p.remaining,'money'],['Upfront cash paid less cash for the same purchases so far',p.cashDifference,'money']],
 note:'Original hypothetical merchant gift-credit arrangement, not a current offer. Cash paid loads equal paid credit plus the entered bonus. Paid and bonus credit form one assumed noncash pool, with no expiry, fees or restrictions on the selected basket during the modeled horizon; actual paid and promotional balances may have different terms. Use is entered as a plan, not a forecast or probability, and occurs uniformly at each month-end. Basket amounts are comparable total checkout amounts; tax is not calculated separately. The alternative pays cash for exactly the same purchases when they occur at the selected lower total price. Prices stay fixed, and no interest, discounting, reward points or extra unplanned purchases are assumed. Remaining credit stays visible and is not written off, refunded or assigned a terminal cash value. The cash-outlay difference is therefore not an overall investment return, saving rate or realized loss. Positive means more cash has been committed to the card than the matched purchases have so far required elsewhere; negative means less.',charts:[
  {id:'gift-credit-balance-ledger',type:'waterfall',title:'Loaded paid credit and bonus credit reconcile to the unspent restricted balance',unit:'money',unitLabel:'Face amount of merchant credit · CAD units, not bank cash',rows:[{label:'Paid amount loaded as credit',value:d.giftCash},{label:'Additional bonus credit',value:p.bonus},{label:'Purchases deducted by horizon',value:-p.used}],totalLabel:'Restricted credit remaining',note:'The first two steps create the assumed card balance. Only the initial cash-paid amount leaves the bank at purchase. The bonus is merchant purchasing credit, not an extra bank deposit. The final balance remains a restricted asset in this illustration; it is not assumed expired or worthless.'},
  {id:'gift-credit-two-percentages',type:'bar',title:'The same bonus has different percentages when the denominator changes',unit:'percent',unitLabel:'Assumes full credit use and identical checkout prices solely for this percentage comparison',rows:[{label:'Bonus ÷ cash paid',value:p.bonusOnPaid},{label:'Bonus ÷ full credit used',value:p.discountAtFullSamePrice}],note:'The first percentage describes added credit relative to cash paid. The second is the discount on the full basket if all loaded credit is used and the same goods cost their face amount in cash. This isolated denominator comparison does not apply the selected partial use or lower competing cash price, which the remaining figures examine.'},
  {id:'gift-credit-cash-calendar',type:'line',title:'Cash is committed upfront while the matched cash alternative pays as purchases occur',unit:'money',xLabel:'Month after card purchase',series:[{name:'Card alternative · cumulative cash paid',step:true,rows:p.rows.map(r=>({x:r.month,value:r.cardCash}))},{name:'Same purchases elsewhere · cumulative cash paid',step:true,dash:true,rows:p.rows.map(r=>({x:r.month,value:r.alternativeCash}))}],note:'These are cumulative outlays, not bank balances or net asset values. The card is paid at month zero. The alternative pays at each assumed month-end purchase. Unspent card credit is not subtracted from the cash-outlay line, so the endpoint difference must be read alongside the restricted balance. Timing costs and returns on cash kept outside the card are excluded.'},
  {id:'gift-credit-use-cash-comparison',type:'signedbar',title:'Less credit use leaves more upfront cash committed compared with purchases received so far',unit:'money',unitLabel:'Card cash paid less cash needed for the same purchases elsewhere · CAD; residual credit kept separate',rows:uses.map(use=>({label:use+'% used'+(use===d.giftUse?' · selected':''),value:giftCreditLedger({...d,giftUse:use}).cashDifference})),note:'Each row is a different use fraction at the selected competing cash-price gap. A positive amount is not a loss estimate: the owner still holds the unspent credit. Negative means the card has required less cash for those matched purchases under the assumptions. No row assumes buying extra goods merely to consume a bonus.'},
  {id:'gift-credit-use-price-matrix',type:'heatmap',signed:true,title:'Planned use and the competing basket price both change the cash comparison',unit:'money',unitLabel:'Upfront card cash paid less matched cash purchases through the horizon · CAD',columns:['0%','5%','10%','15%'],rows:[25,50,75,100].map(use=>({label:use+'% used',values:[0,5,10,15].map(gap=>giftCreditLedger({...d,giftUse:use,cashPriceGap:gap}).cashDifference)})),note:'Rows replace the credit-use fraction; columns replace how much lower the same checkout basket costs elsewhere. Cash loaded and the bonus percentage stay selected. Every cell excludes a terminal cash value for remaining card credit, while keeping that credit owned rather than written off. It is a cash-commitment comparison, not a probability grid or a final economic-profit calculation.'}
 ]};
}
